import React from 'react';
import MotionReveal, { staggerDelay } from '../../motion/MotionReveal.jsx';
import AnimatedText from '../../motion/AnimatedText.jsx';
import OutlineIcon from '../../components/icons/OutlineIcon.jsx';
import ContactForm from './ContactForm.jsx';
import SplineScene from './SplineScene.jsx';
import './Contact.css';

const REACH = [
  { icon: 'pin', href: null, label: 'Kasturi Nagar, Bangalore' },
  { icon: 'phone', href: 'tel:+919008804368', label: '+91 90088 04368' },
  { icon: 'phone', href: 'tel:+916366018352', label: '+91 63660 18352' },
  { icon: 'mail', href: 'mailto:info@mapmycareer360.com', label: 'info@mapmycareer360.com' },
  { icon: 'whatsapp', href: 'https://wa.link/czgq77', label: 'WhatsApp a counsellor', external: true },
];

export default function Contact() {
  return (
    <div className="mmc-contact-page">
      <section className="container mmc-contact-shell">
        <MotionReveal className="mmc-contact-head">
          <p className="mmc-section-eyebrow">Contact us</p>
          <h1><AnimatedText>Contact Us</AnimatedText></h1>
          <p>Have a question or want to know more? We'd love to hear from you.</p>
        </MotionReveal>

        <div className="mmc-contact-split">
          <MotionReveal className="mmc-contact-visual" delay={90}>
            <SplineScene />
          </MotionReveal>

          <MotionReveal className="mmc-contact-panel" delay={140}>
            <ContactForm />
          </MotionReveal>
        </div>

        <ul className="mmc-contact-reach">
          {REACH.map((item, index) => (
            <MotionReveal as="li" key={item.label} delay={staggerDelay(index, 50, 80)}>
              <OutlineIcon name={item.icon} size={16} />
              {item.href ? (
                <a
                  href={item.href}
                  {...(item.external ? { target: '_blank', rel: 'noreferrer' } : {})}
                >
                  {item.label}
                </a>
              ) : (
                <span>{item.label}</span>
              )}
            </MotionReveal>
          ))}
        </ul>
      </section>
    </div>
  );
}
